// Reuse the approved artwork as CSS image crops; all navigation and copy remain HTML.
landing = function () {
 const dropdown=(label,items)=>`<details class="front-dropdown"><summary>${label}<span aria-hidden="true">⌄</span></summary><div class="front-menu">${items.map(([ic,text,url])=>`<a href="${url}">${icon(ic)}${text}</a>`).join('')}</div></details>`;
 const tracks=[['Builder','For developers, engineers and data/AI practitioners.','Python Required','4 Programs',490,'code'],['No Code','For domain experts, analysts, operations staff and managers.','No Coding Required','3 Programs',746,'spark'],['Business & Leadership','For managers, product leaders and executives.','None to Light Coding','2 Programs',1002,'folder'],['Industry','For finance and healthcare professionals.','Light Coding (Optional)','2 Programs',1258,'shield']];
 return `<div class="approved-front"><div class="front-top"><span>A SCHOLARION GLOBAL LEARNING PLATFORM</span><div><a href="#signin">Learner Portal</a><span>|</span><a href="#organizations">Partner With Us</a><span>|</span><a href="#help">Support</a><span>|</span><span>◎ English</span></div></div><header class="front-nav"><a href="#home" aria-label="Scholarion home" class="front-logo"><img src="assets/approved-homepage.png" alt="Scholarion — Learn. Earn. Build Your Future."></a><nav aria-label="Academy navigation"><a class="front-active" href="#home">Home</a>${dropdown('Programs',[['code','Builder programs','#programs'],['spark','No-code programs','#programs'],['folder','Business & Leadership','#programs'],['shield','Industry programs','#programs']])}${dropdown('LMS',[['chart','LMS Overview','#about'],['book','For Learners','#dashboard'],['book','For Faculty','#faculty'],['shield','For Administrators','#admin'],['folder','Features','#experience'],['spark','Take a Tour','#module']])}${dropdown('Learning Experience',[['book','Guided modules','#module'],['lab','Hands-on labs','#lab'],['folder','Applied projects','#projects'],['award','Certificates of completion','#credentials']])}<a href="#admissions">Admissions</a>${dropdown('For Organizations',[['globe','Partner with Scholarion','#organizations']])}${dropdown('About',[['globe','Scholarion Global Learning','#about']])}<a href="#courses" class="front-search" aria-label="Search courses">${icon('search')}</a></nav><div class="front-auth">${btn('Sign In','#signin',true)}${btn('Enroll Now','#admissions')}</div></header><main><section class="front-hero"><div class="front-hero-art" role="img" aria-label="A smiling learner using a laptop beside a stack of books in a modern learning space"></div><div class="front-hero-copy"><div class="eyebrow">SKILLS TODAY. OPPORTUNITIES TOMORROW.</div><h1>Scholarion<br><em>AI</em> Academy</h1><h2>Learn AI. Earn Credentials. Build Your Future.</h2><p>Practical, hands-on AI certificate programs designed for learners, professionals, and organizations. Gain real skills. Build real solutions. Make a real impact.</p><div class="front-actions">${btn('Explore Programs','#programs')}<button class="button front-watch" data-action="front-video">Watch Video <span aria-hidden="true">▷</span></button></div><div class="front-highlights">${[['award','11 Certificate','Programs'],['book','Flexible Learning','(Self-Paced + Live)'],['shield','Verifiable Digital','Credentials'],['folder','Real-World Projects','& Career Support']].map(([ic,a,b])=>`<div>${icon(ic)}<span>${a}<br>${b}</span></div>`).join('')}</div></div></section><section class="front-values" aria-label="Our learning values">${[['globe','Global Learning Community','Join learners worldwide'],['chart','Industry-Relevant Skills','Tools. Projects + Portfolio.'],['globe','Learn From Anywhere','On your schedule.'],['shield','Responsible AI','Ethical. Safe. Human-Centered.'],['spark','Make an Impact','People. Organizations. Communities.']].map(([ic,a,b])=>`<div>${icon(ic)}<span><b>${a}</b><small>${b}</small></span></div>`).join('')}</section><section class="front-programs" id="programs"><div class="front-program-intro"><div class="eyebrow">OUR PROGRAMS</div><h2>11 Certificate Programs<br>for the AI-Powered Future</h2><p>Original, hands-on programs designed for real-world success. No degrees. No fluff. Just practical skills, expert guidance, and verifiable credentials.</p><button class="button" data-action="program-catalog">View All Programs <span aria-hidden="true">→</span></button></div>${tracks.map(([name,desc,req,count,x,ic],i)=>`<a class="front-track" href="#program-track/${i}"><div class="front-track-art"><img src="assets/approved-homepage.png" alt="${name} learning pathway" style="left:-${x/235*100}%"></div><div class="front-track-body"><h3>${name}</h3><p>${desc}</p><span class="front-requirement ${i===3?'green':''}">${icon(ic)}${req}</span><strong>${count}</strong></div></a>`).join('')}</section><section class="front-bottom" id="experience"><blockquote>“Education transforms lives.<br>AI expands what’s possible.”<cite>— SCHOLARION AI ACADEMY</cite></blockquote>${[['spark','Learn','Gain in-demand skills.'],['lab','Practice','Build real projects.'],['award','Earn','Get a verifiable credential.'],['book','Advance','Grow your career.'],['globe','Impact','Create a better tomorrow.']].map(([ic,a,b])=>`<div>${icon(ic)}<b>${a}</b><small>${b}</small></div>`).join('')}${btn('Start Your Journey →','#admissions')}</section><footer class="front-preview-note">Design preview · Proposed program catalog and services · Enrollment is not yet open</footer></main></div>`;
};
const originalRender=render;
render=function(){let r=location.hash.slice(1);if(['faculty','admin','admissions','organizations'].includes(r)||r.startsWith('program-track/')){const tracks=['Builder','No Code','Business & Leadership','Industry'];let title,description,body;if(r.startsWith('program-track/')){title=tracks[Number(r.split('/')[1])]||'Certificate programs';description='Proposed certificate pathway';body='<p>Detailed program curricula and enrollment dates are being prepared. Explore the learner walkthrough to see how lessons, labs, projects, and completion certificates fit together.</p>'+btn('Explore the learner experience','#dashboard');}else{const pages={faculty:['Faculty workspace','Teaching and course management','The faculty workspace will support course content, assignment review, learner feedback, and grade management. This area is planned; instructor accounts are not connected.'],admin:['Administrator workspace','Academy operations','The administrator workspace will support programs, enrollments, roles, and academy operations. Administrative services are not connected in this preview.'],admissions:['Start your Scholarion journey','Certificate programs · Admissions','Enrollment is not yet open. This preview introduces the proposed learning experience. Explore the demo before programs and enrollment dates are finalized.'],organizations:['Partner with Scholarion','Learning for teams and organizations','The academy is being designed for practical AI learning across organizations. Partnership information and a contact channel will be added before launch.']};[title,description,body]=pages[r];body='<p>'+body+'</p>'+btn('Explore the learner demo','#dashboard');}document.getElementById('app').innerHTML=shell(r,heading(title,description)+`<section class="card prose">${body}</section>`);bind();document.title=title+' · Scholarion';return;}originalRender();};
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='front-video')modal('Explore the Scholarion learning experience','<p>A promotional video has not been supplied yet. You can explore the working learner walkthrough now.</p>'+btn('Take the interactive tour','#module'));if(action==='program-catalog')modal('11 proposed certificate programs','<p><strong>Builder:</strong> 4 programs</p><p><strong>No Code:</strong> 3 programs</p><p><strong>Business & Leadership:</strong> 2 programs</p><p><strong>Industry:</strong> 2 programs</p><p>Program names, curricula, and enrollment dates will be finalized before launch.</p>'+btn('Explore the learning experience','#dashboard'));if(e.target.closest('#modal a'))document.getElementById('modal').close();const selected=e.target.closest('details');document.querySelectorAll('.front-dropdown[open]').forEach(d=>{if(d!==selected)d.open=false;});});
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.front-dropdown[open]').forEach(d=>d.open=false)});
render();
